document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("enrollForm");e&&e.addEventListener("submit",async t=>{t.preventDefault();const n=e.querySelector('button[type="submit"]'),r=n.innerHTML;try{n.disabled=!0,n.innerHTML='<i data-lucide="loader-2" class="w-5 h-5 animate-spin"></i> Processing...',window.lucide&&window.lucide.createIcons();const t=new FormData(e),r=Object.fromEntries(t.entries());let a=[];try{r.children_data&&(a=JSON.parse(r.children_data))}catch(e){console.error("Error parsing children data",e)}const i={student_first_name:r.student_first_name,student_last_name:r.student_last_name,student_age:parseInt(r.student_age)||0,student_gender:r.student_gender,parent_name:r.parent_name,email:r.email,phone:r.phone,program_interest:r.program,experience_level:r.experience,referral_source:r.referral,status:"pending",children_data:a,created_at:(new Date).toISOString()};if(!window.supabase)throw new Error("Supabase client not initialized");const{error:s}=await window.supabase.from("enrollments").insert([i]);if(s)throw s;window.confetti&&window.confetti({particleCount:100,spread:70,origin:{y:.6}}),e.innerHTML=`\n                    <div class="text-center py-12">\n                        <div class="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6">\n                            <i data-lucide="check" class="w-10 h-10 text-green-600"></i>\n                        </div>\n                        <h2 class="text-3xl font-bold text-gray-800 mb-4">Enrollment Received! <span data-icon-3d="rocket" data-icon-size="24"></span></h2>\n                        <p class="text-gray-600 mb-8">Thank you, ${r.parent_name}. We have received your application. <br>Our admissions team will contact you at <strong>${r.email}</strong> shortly.</p>\n                        <a href="index.html" class="bg-orange-500 text-white px-8 py-3 rounded-full font-bold hover:bg-orange-600 transition-colors">Return Home</a>\n                    </div>\n                `,window.lucide&&window.lucide.createIcons(),window.NotificationService&&window.NotificationService.notifyNewEnrollment(i)}catch(e){console.error("Enrollment Error:",e),alert("Something went wrong. Please try again or contact support."),n.disabled=!1,n.innerHTML=r}});const t=document.getElementById("contact-form");t&&t.addEventListener("submit",async e=>{e.preventDefault();const n=t.querySelector('button[type="submit"]'),r=n.innerHTML;try{n.disabled=!0,n.innerText="Sending...";const e=new FormData(t),r=Object.fromEntries(e.entries()),a={first_name:r["first-name"],last_name:r["last-name"],email:r.email,subject:r.subject,message:r.message,status:"unread",created_at:(new Date).toISOString()};if(!window.supabase)throw new Error("Supabase client not initialized");const{error:i}=await window.supabase.from("messages").insert([a]);if(i)throw i;t.innerHTML='\n                    <div class="text-center py-8">\n                        <div class="inline-flex items-center justify-center w-16 h-16 rounded-full bg-green-100 mb-4">\n                            <i data-lucide="send" class="w-8 h-8 text-green-600"></i>\n                        </div>\n                        <h3 class="text-2xl font-bold text-gray-800 mb-2">Message Sent!</h3>\n                        <p class="text-gray-600">Thanks for reaching out. We\'ll get back to you soon.</p>\n                    </div>\n                ',window.lucide&&window.lucide.createIcons()}catch(e){console.error("Contact Error:",e),alert("Failed to send message. Please try again."),n.disabled=!1,n.innerHTML=r}})});